func toWebhookGetJSON(wh apitype.Webhook) webhookGetJSON {
	format := ""
	if wh.Format != nil {
		format = *wh.Format
	}
	groups := wh.Groups
	if groups == nil {
		groups = []string{}
	}
	filters := wh.Filters
	if filters == nil {
		filters = []string{}
	}
	projectName := ""
	if wh.ProjectName != nil {
		projectName = *wh.ProjectName
	}
	stackName := ""
	if wh.StackName != nil {
		stackName = *wh.StackName
	}
	envName := ""
	if wh.EnvName != nil {
		envName = *wh.EnvName
	}
	return webhookGetJSON{
		OrganizationName: wh.OrganizationName,
		ProjectName:      projectName,
		StackName:        stackName,
		EnvName:          envName,
		ID:               wh.Name,
		Name:             wh.DisplayName,
		URL:              wh.PayloadURL,
		Format:           format,
		Active:           wh.Active,
		Groups:           groups,
		Filters:          filters,
		HasSecret:        wh.HasSecret,
		SecretCiphertext: wh.SecretCiphertext,
	}
}

func renderWebhookGetJSON(w io.Writer, webhook apitype.Webhook) error {
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	return enc.Encode(toWebhookGetJSON(webhook))
}

func renderWebhookGetText(w io.Writer, wh apitype.Webhook) error {
	format := ""
	if wh.Format != nil {
		format = *wh.Format
	}
	active := "yes"
	if !wh.Active {
		active = "no"
	}
	hasSecret := "no"
	if wh.HasSecret {
