// scheduleDefinition parses the deployment definition embedded in a scheduled action.
// It returns the underlying deployment request when present.
func scheduleDefinition(s apitype.ScheduledAction) *apitype.CreateDeploymentRequest {
	if len(s.Definition) == 0 {
		return nil
	}
	var def apitype.ScheduledDeploymentDefinition
	if err := json.Unmarshal(s.Definition, &def); err != nil {
