// toScheduleSummary flattens a scheduled action into a human-readable summary,
// inferring the schedule type from the definition and timing fields.
func toScheduleSummary(s apitype.ScheduledAction) scheduleSummary {
	var op apitype.PulumiOperation
	var opts *apitype.OperationContextOptions
	if req := scheduleDefinition(s); req != nil {
		op = req.Op
		if req.Operation != nil {
