// scheduleListRenderer selects the list renderer based on the --output flag.
func scheduleListRenderer(output string) (scheduleListRenderFunc, error) {
	switch output {
	case "", "default", "table":
		return renderScheduleListTable, nil
	case "json":
		return renderScheduleListJSON, nil
	default:
		return nil, fmt.Errorf("invalid --output value %q: expected \"default\", \"table\", or \"json\"", output)
	}
}

// scheduleGetRenderer selects the single-schedule renderer based on the --output flag.
func scheduleGetRenderer(output string) (scheduleGetRenderFunc, error) {
	switch output {
	case "", "default":
		return renderScheduleGetText, nil
	case "json":
		return renderScheduleGetJSON, nil
	default:
		return nil, fmt.Errorf("invalid --output value %q: expected \"default\" or \"json\"", output)
	}
}

func newStackScheduleListCmd() *cobra.Command {
	var (
		stack  string
		output string
		count  int
	)

	cmd := &cobra.Command{
		Hidden: true,
		Use:    "list",
		Short:  "List all scheduled actions configured for a stack",
		Long:   "[EXPERIMENTAL] List all scheduled actions configured for a stack.",
		RunE: func(cmd *cobra.Command, args []string) error {
			render, err := scheduleListRenderer(output)
			if err != nil {
				return err
			}
			factory := func(
				ctx context.Context, stackFlag string,
			) (stackScheduleListClient, client.StackIdentifier, error) {
				return RequireCloudStack(
					ctx, cmdutil.Diag(), pkgWorkspace.Instance, cmdBackend.DefaultLoginManager, stackFlag)
			}
			return runStackScheduleList(cmd.Context(), cmd.OutOrStdout(), factory, stack, count, render)
		},
	}

	constrictor.AttachArguments(cmd, constrictor.NoArgs)

	cmd.Flags().StringVarP(&stack, "stack", "s", "",
